// Package argparse is a minimal command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name, usage, def string
	b                *bool
	s                *string
}

type Parser struct {
	name  string
	flags []*flag
}

func New(name string) *Parser { return &Parser{name: name} }

// Bool defines a boolean flag that is false unless given.
func (p *Parser) Bool(name, usage string) *bool {
	v := new(bool)
	p.flags = append(p.flags, &flag{name: name, usage: usage, b: v})
	return v
}

// String defines a flag that takes a value, as --name value or --name=value.
func (p *Parser) String(name, def, usage string) *string {
	v := &def
	p.flags = append(p.flags, &flag{name: name, usage: usage, def: def, s: v})
	return v
}

// Parse sets the defined flags from args and returns the positional
// arguments. Everything after a bare "--" is positional.
func (p *Parser) Parse(args []string) ([]string, error) {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			return append(pos, args[i+1:]...), nil
		}
		if len(a) < 2 || a[0] != '-' {
			pos = append(pos, a)
			continue
		}
		name, val, hasVal := strings.Cut(strings.TrimPrefix(a[1:], "-"), "=")
		if name == "h" || name == "help" {
			return nil, ErrHelp
		}
		var f *flag
		for _, c := range p.flags {
			if c.name == name {
				f = c
			}
		}
		if f == nil {
			return nil, fmt.Errorf("unknown flag: %s", a)
		}
		if f.b != nil {
			b := true
			if hasVal {
				var err error
				if b, err = strconv.ParseBool(val); err != nil {
					return nil, fmt.Errorf("invalid boolean for --%s: %q", name, val)
				}
			}
			*f.b = b
			continue
		}
		if !hasVal {
			if i++; i == len(args) {
				return nil, fmt.Errorf("flag --%s needs a value", name)
			}
			val = args[i]
		}
		*f.s = val
	}
	return pos, nil
}

// Usage writes a help message generated from the flag definitions.
func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags] [args...]\n\nFlags:\n", p.name)
	for _, f := range p.flags {
		name, usage := "--"+f.name, f.usage
		if f.s != nil {
			name += " <value>"
			if f.def != "" {
				usage += fmt.Sprintf(" (default %q)", f.def)
			}
		}
		fmt.Fprintf(w, "  %-24s %s\n", name, usage)
	}
	fmt.Fprintf(w, "  %-24s %s\n", "-h, --help", "show this help")
}
